s($,"aTf","Hc",()=>{var q,p,o,n,m,l,k,j,i,h,g=63.66197723675813*A.o5(50)/100,f=A.auQ(0.1,50),e=$.ra[0],d=$.ra[1],c=$.ra[2],b=e*0.401288+d*0.650173+c*-0.051461,a=e*-0.250268+d*1.204414+c*0.045854,a0=e*-0.002079+d*0.048952+c*0.953127,a1=A.atb(0.59,0.69,0.9999999999999998),a2=1-0.2777777777777778*A.aPy((-g-42)/92)
if(a2>1)a2=1
else if(a2<0)a2=0
q=A.b([a2*(100/b)+1-a2,a2*(100/a)+1-a2,a2*(100/a0)+1-a2],t.n)
e=5*g
p=1/(e+1)
o=p*p*p*p
n=1-o
m=o*g+0.1*n*n*A.GW(e,0.3333333333333333)
l=A.o5(f)/$.ra[1]
e=A.aQx(l)
k=0.725/A.GW(l,0.2)
j=[A.GW(m*q[0]*b/100,0.42),A.GW(m*q[1]*a/100,0.42),A.GW(m*q[2]*a0/100,0.42)]
d=j[0]
c=j[1]
i=j[2]
h=[400*d/(d+27.13),400*c/(c+27.13),400*i/(i+27.13)]
return new A.aft(l,(40*h[0]+20*h[1]+h[2])/20*k,k,k,a1,1,q,m,A.GW(m,0.25),1.48+e)})
